    `Seat bar: ${thr} seats; the tracker's own projection sits ${seats >= thr ? "+" : ""}${seats - thr} seats relative to it`,
  ];
  const headline =
    `Live provincial tracker (Data10 via Electografía, fetched ${ctx.now.toISOString().slice(0, 10)}): Vox polls at ${share.toFixed(1)}% nationally ` +
    `and projects to ${seats} Congress of Deputies seats — ${seats >= thr ? `above` : `below`} the ${thr}-seat bar — using its own D'Hondt-style provincial seat model.`;

  const links: SourceLink[] = [
    {
      url: trackingDoc.url,
      label: "Electografía/Data10 26N general-election tracking (Vox: vote share + seats)",
      lang: "es",
      access: "scraped",
      expect: [voteShareM[1], seatsFromText],
    },
  ];
  return assemble(
    seed,
    [trackingDoc],
